m=json.loads((src/'build-manifest.json').read_text());selected=json.loads((dst/'job-variants.json').read_text());variants=set(v for vs in selected.values() for v in vs)
for v in variants:
 for p in [0,1]:
  key=f'{v}-p{p}'; assert key in m['binaries'],key
  for name,hashkey in [('walk','walk_sha256'),('query-workload','binary_sha256')]:
   assert hashlib.sha256((src/'binaries'/key/name).read_bytes()).hexdigest()==m['binaries'][key][hashkey]
