scripts.summarize-columns.py:
import json,math,statistics as st
from collections import defaultdict
from pathlib import Path
b=Path('build/column-probes-cloud')
def gm(xs):return math.exp(st.mean(math.log(x) for x in xs))
query=json.loads((b/'column-query-summary.json').read_text());walk=json.loads((b/'column-walk-summary.json').read_text())
qr=query['rows'];wr=walk['rows'];raw=json.loads((b/'column-walks.json').read_text());jobs={j['name']:j for j in raw['jobs']}
layout={}
for r in raw['records']:
 if r['returncode']==0:layout[(r['points'],r['job'],r['variant'])]=r['measured']
def time_for(rows,p,v,k,op):
 rs=[r for r in rows if (r['points'],r['variant'],r['kind'],r['operation'])==(p,v,k,op)]
 if not rs:return None
 gs=defaultdict(list)
 for r in rs:gs[r['grammar']].append(r['ratio'])
 return 100*(gm(gm(xs) for xs in gs.values())-1)
def memory_for(p,v):
 gs=defaultdict(list)
 for (pt,j,variant),m in layout.items():
  if (pt,variant)!=(p,v):continue
  gs[jobs[j]['grammar_name']].append(m['slab_bytes']/layout[(p,j,'exact')]['slab_bytes'])
 return 100*(gm(gm(xs) for xs in gs.values())-1)
rows=[]
for p in [1,0]:
 for v in ['field2','field5','field6','symbol5','symbol6','symbol9','symbol10','both','super']:
  rows.append(dict(points=p,variant=v,highlight=time_for(qr,p,v,'highlights','query'),tags=time_for(qr,p,v,'tags','query'),supertype_query=time_for(qr,p,v,'supertype','query'),cursor_walk=time_for(wr,p,v,'walk','cursor_walk'),uncached=time_for(wr,p,v,'walk','uncached'),cached=time_for(wr,p,v,'walk','cached'),membership_walk=time_for(wr,p,v,'walk','membership_walk'),memory=memory_for(p,v)))
# Per-grammar supertype results include actual widths and aggregate fixture sizes.
superrows=[]
for p in [1,0]:
 for g in sorted({j['grammar_name'] for j in jobs.values()}):
  ids=[j for j in jobs if jobs[j]['grammar_name']==g]
  sample=layout[(p,ids[0],'super')]
  rr=dict(points=p,grammar=g,supertype_count=sample['supertype_count'],dictionary_count=sample['dictionary_count'],supertype_bits=sample['supertype_bits'],memory=100*(gm(layout[(p,j,'super')]['slab_bytes']/layout[(p,j,'exact')]['slab_bytes'] for j in ids)-1))
  for kind in ['highlights','tags','supertype']:
   ratios=[r['ratio'] for r in qr if (r['points'],r['variant'],r['grammar'],r['kind'])==(p,'super',g,kind)]
   rr[kind]=100*(gm(ratios)-1) if ratios else None
  for op in ['cached','uncached','cursor_walk','membership_walk']:
   ratios=[r['ratio'] for r in wr if (r['points'],r['variant'],r['grammar'],r['operation'])==(p,'super',g,op)]
   rr[op]=100*(gm(ratios)-1)
  superrows.append(rr)
(b/'column-tables.json').write_text(json.dumps(dict(transitions=rows,supertypes=superrows),indent=2)+'\n')
def fmt(x):return '—' if x is None else f'{x:+.1f}%'
lines=[]
for p in [1,0]:
 lines += ['### '+('Points enabled' if p else 'Points disabled'),'','| Only this transition | Highlight | Tags | Cursor walk | Uncached walk | Cached walk | Slab bytes |','|---|---:|---:|---:|---:|---:|---:|']
 for r in rows:
  if r['points']!=p or r['variant'] in ['super']:continue
  v=r['variant'];label='Field ≥6→8 + symbol ≥9→16' if v=='both' else v.replace('field','Field ID ').replace('symbol','Symbol ')+('→8' if int(v.lstrip('fieldsymbo'))<8 else '→16')
  lines+=['| '+label+' | '+' | '.join(fmt(r[k]) for k in ['highlight','tags','cursor_walk','uncached','cached','memory'])+' |']
lines+=['','### Variable-width supertypes','','| Build | Highlight | Tags | Supertype query | Cursor walk | Uncached walk | Cached walk | Membership walk | Slab bytes |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in rows:
 if r['variant']=='super':lines+=['| '+('Points' if r['points'] else 'Byte-only')+' | '+' | '.join(fmt(r[k]) for k in ['highlight','tags','supertype_query','cursor_walk','uncached','cached','membership_walk','memory'])+' |']
for p in [1,0]:
 lines+=['','### Supertype results by grammar — '+('points' if p else 'byte-only'),'','| Grammar | Supertypes / dictionary entries | Width | Highlight | Tags | Supertype query | Membership walk | Slab bytes |','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in superrows:
  if r['points']==p:lines+=['| '+r['grammar']+f" | {r['supertype_count']} / {r['dictionary_count']} | 8→{r['supertype_bits']} | "+' | '.join(fmt(r[k]) for k in ['highlights','tags','supertype','membership_walk','memory'])+' |']
(b/'tables.md').write_text('\n'.join(lines)+'\n')

